import {
  fireEvent,
  render,
  screen,
  waitFor,
} from "@testing-library/react-native";

import { InvalidEmailError } from "./session";
import { SignInScreen } from "./sign-in-screen";

const mockSignIn = jest.fn();
const mockTrackScreenView = jest.fn();
const mockUseSession = jest.fn();
const mockRedirect = jest.fn();
let mockSearchParams: { next?: string } = {};

const SIGNED_OUT = {
  session: null,
  status: "ready" as const,
  signIn: mockSignIn,
  signOut: jest.fn(),
};

const SIGNED_IN = {
  session: { accountId: "local-1", email: "person@example.com" },
  status: "ready" as const,
  signIn: mockSignIn,
  signOut: jest.fn(),
};

jest.mock("./session-context", () => ({
  useSession: () => mockUseSession(),
}));

jest.mock("@/analytics/analytics", () => ({
  trackScreenView: (...args: unknown[]) => mockTrackScreenView(...args),
}));

jest.mock("expo-router", () => ({
  useLocalSearchParams: () => mockSearchParams,
  Redirect: ({ href }: { href: unknown }) => {
    mockRedirect(href);
    return null;
  },
}));

beforeEach(() => {
  mockSignIn.mockReset();
  mockTrackScreenView.mockReset();
  mockRedirect.mockReset();
  mockUseSession.mockReset().mockReturnValue(SIGNED_OUT);
  mockSearchParams = {};
});

describe("SignInScreen", () => {
  it("tracks a screen view on mount", async () => {
    await render(<SignInScreen />);

    expect(mockTrackScreenView).toHaveBeenCalledWith("Sign In");
  });

  it("shows a validation error for a malformed address", async () => {
    mockSignIn.mockRejectedValueOnce(new InvalidEmailError("not-an-email"));
    await render(<SignInScreen />);

    await fireEvent.changeText(
      screen.getByTestId("sign-in-email"),
      "not-an-email",
    );
    await fireEvent.press(screen.getByTestId("sign-in-submit"));

    await waitFor(() =>
      expect(screen.getByTestId("sign-in-email-error")).toHaveTextContent(
        '"not-an-email" is not a valid email address.',
      ),
    );
  });

  it("shows a pending state while signing in, then clears it", async () => {
    let resolveSignIn: () => void = () => {};
    mockSignIn.mockReturnValueOnce(
      new Promise<void>((resolve) => {
        resolveSignIn = resolve;
      }),
    );
    await render(<SignInScreen />);

    await fireEvent.changeText(
      screen.getByTestId("sign-in-email"),
      "person@example.com",
    );
    // Not awaited: this press's handler awaits `signIn`, which this test
    // deliberately leaves unresolved until `resolveSignIn()` below — so
    // awaiting the press itself here would wait for that handler to finish
    // and deadlock before the test ever gets to resolve it.
    fireEvent.press(screen.getByTestId("sign-in-submit"));

    await waitFor(() =>
      expect(screen.getByTestId("sign-in-submit")).toHaveTextContent(
        "Signing in…",
      ),
    );

    resolveSignIn();

    await waitFor(() =>
      expect(screen.getByTestId("sign-in-submit")).toHaveTextContent("Sign in"),
    );
    expect(mockSignIn).toHaveBeenCalledWith("person@example.com");
  });

  it("redirects to the deck list when reached directly, with no destination on the URL", async () => {
    mockUseSession.mockReturnValue(SIGNED_IN);

    await render(<SignInScreen />);

    expect(mockRedirect).toHaveBeenCalledWith("/");
  });

  it("redirects to the deck a `next` param names, when reached already signed in", async () => {
    mockSearchParams = { next: "/decks/world-capitals" };
    mockUseSession.mockReturnValue(SIGNED_IN);

    await render(<SignInScreen />);

    expect(mockRedirect).toHaveBeenCalledWith("/decks/world-capitals");
  });

  it("falls back to the deck list for a `next` param that doesn't name a path within the app", async () => {
    mockSearchParams = { next: "https://evil.example/phish" };
    mockUseSession.mockReturnValue(SIGNED_IN);

    await render(<SignInScreen />);

    expect(mockRedirect).toHaveBeenCalledWith("/");
  });

  it("redirects to the `next` destination once sign-in succeeds", async () => {
    mockSearchParams = { next: "/decks/world-capitals" };
    mockSignIn.mockImplementationOnce(async () => {
      mockUseSession.mockReturnValue(SIGNED_IN);
    });
    await render(<SignInScreen />);

    await fireEvent.changeText(
      screen.getByTestId("sign-in-email"),
      "person@example.com",
    );
    await fireEvent.press(screen.getByTestId("sign-in-submit"));

    await waitFor(() =>
      expect(mockRedirect).toHaveBeenCalledWith("/decks/world-capitals"),
    );
  });
});

